import sys
from collections import deque

def get_level_order(root):
    if not root:
        return []
    levels = []
    queue = deque([root])
    while queue:
        level_size = len(queue)
        current_level = []
        for _ in range(level_size):
            node = queue.popleft()
            current_level.append(node.data)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        levels.append(current_level)
    return levels

def are_anagrams(list1, list2):
    if len(list1) != len(list2):
        return False
    sorted1 = sorted(list1)
    sorted2 = sorted(list2)
    return sorted1 == sorted2

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes, index):
    if index >= len(nodes):
        return None
    if nodes[index] == -1:
        return None
    node = Node(nodes[index])
    node.left = build_tree(nodes, 2 * index + 1)
    node.right = build_tree(nodes, 2 * index + 2)
    return node

def main():
    try:
        input_data = sys.stdin.read().split()
    except Exception:
        return

    if not input_data:
        print(0)
        return

    iterator = iter(input_data)

    try:
        n1 = int(next(iterator))
        nodes1 = []
        for _ in range(n1):
            val = int(next(iterator))
            nodes1.append(val)

        n2 = int(next(iterator))
        nodes2 = []
        for _ in range(n2):
            val = int(next(iterator))
            nodes2.append(val)
    except StopIteration:
        print(0)
        return

    root1 = build_tree(nodes1, 0)
    root2 = build_tree(nodes2, 0)

    levels1 = get_level_order(root1)
    levels2 = get_level_order(root2)

    if len(levels1) != len(levels2):
        print(0)
        return

    for l1, l2 in zip(levels1, levels2):
        if not are_anagrams(l1, l2):
            print(0)
            return

    print(1)

if __name__ == "__main__":
    main()
